async def act(page):
    """
    Create a simple product "Energy-Bulk Women Shirt" with 50 in stock,
    size S and color Blue, price $60.

    Plan:
    - Use a relative goto to the new product page (avoids clicking site navigation links).
    - Handle the initial Attribute Set / Product Type selector if present (select Default / Simple Product and Continue).
    - Fill main product fields: Name, SKU, Price.
    - Open Inventory tab and set Qty to 50 and mark In Stock.
    - Select Size = S and Color = Blue via combobox selects (use several label fallbacks).
    - Click Save (final action) using get_by_role selectors.

    Note: No external knowledge_base functions are available, so all interactions use Playwright APIs.
    """

    # Navigate directly to the new-product page using a relative URL
    await page.goto("/index.php/admin/catalog_product/new/")
    await page.wait_for_load_state("networkidle")

    # Utility helpers that use accessibility-role-centric selectors
    async def try_click(locator):
        try:
            await locator.click()
            return True
        except Exception:
            return False

    async def try_select_combobox_by_label(locator, *labels):
        # locator is a Locator from get_by_role("combobox")
        for lbl in labels:
            try:
                await locator.select_option(label=lbl)
                return True
            except Exception:
                try:
                    # try selecting by value fallback
                    await locator.select_option(value=lbl)
                    return True
                except Exception:
                    continue
        return False

    async def try_fill_textbox_by_names(*names, value):
        for n in names:
            try:
                tb = page.get_by_role("textbox", name=n)
                # ensure it exists (count) before filling
                if await tb.count() > 0:
                    await tb.fill(value)
                    return True
            except Exception:
                continue
        return False

    # 1) Handle initial selection step (Attribute Set / Product Type) if present
    # Try to find a combobox that contains an option named 'Default' and select it,
    # then choose Simple Product radio and click Continue.
    try:
        # find a combobox that has the option Default
        comboboxes = page.get_by_role("combobox")
        attr_set_handled = False
        # iterate comboboxes to find one that can select 'Default'
        count_comboboxes = await comboboxes.count()
        for i in range(count_comboboxes):
            cb = comboboxes.nth(i)
            try:
                # if the combobox has an option named Default, try selecting it
                # we attempt selection using label 'Default'
                if await cb.select_option(label="Default") is not None:
                    attr_set_handled = True
                    break
            except Exception:
                # ignore and continue
                pass

        # Try to select product type radio 'Simple Product' if present
        try:
            rp = page.get_by_role("radio", name="Simple Product")
            if await rp.count() > 0:
                await rp.check()
        except Exception:
            # fallback: try radio named 'Simple'
            try:
                rp2 = page.get_by_role("radio", name="Simple")
                if await rp2.count() > 0:
                    await rp2.check()
            except Exception:
                pass

        # If the Continue button is present, click it to proceed to product form
        cont_btn = page.get_by_role("button", name="Continue")
        if await cont_btn.count() > 0:
            # Clicking Continue will navigate to the actual product form; wait after clicking
            await cont_btn.click()
            await page.wait_for_load_state("networkidle")
    except Exception:
        # It's fine if the initial selection step isn't present; continue
        pass

    # 2) Fill product main fields: Name, SKU, Price
    await page.wait_for_timeout(500)

    # Fill product name (try multiple common label variants)
    await try_fill_textbox_by_names("Name", "Product Name", "name", value="Energy-Bulk Women Shirt")

    # Fill SKU
    await try_fill_textbox_by_names("SKU", "sku", value="ENERGY-BULK-W-S")

    # Fill Price
    await try_fill_textbox_by_names("Price", "price", value="60")

    # 3) Inventory: open Inventory tab if available and set Qty and In Stock
    try:
        inv_tab = page.get_by_role("tab", name="Inventory")
        if await inv_tab.count() > 0:
            await inv_tab.click()
            await page.wait_for_timeout(300)
    except Exception:
        # fallback: try a tab named 'Stock' or 'Stocks'
        try:
            stock_tab = page.get_by_role("tab", name="Stock")
            if await stock_tab.count() > 0:
                await stock_tab.click()
                await page.wait_for_timeout(300)
        except Exception:
            pass

    # Set quantity: try common label names
    await try_fill_textbox_by_names("Qty", "Quantity", "qty", "Quantity In Stock", value="50")

    # Set In Stock: try combobox/option labeled 'In Stock' or 'Yes'
    try:
        stock_comboboxes = page.get_by_role("combobox")
        for i in range(await stock_comboboxes.count()):
            cb = stock_comboboxes.nth(i)
            # try selecting common labels
            if await try_select_combobox_by_label(cb, "In Stock", "Yes", "1"):
                break
    except Exception:
        pass

    # 4) Select Size = S and Color = Blue
    # Try to find comboboxes with those names and select options
    try:
        size_comb = page.get_by_role("combobox", name="Size")
        if await size_comb.count() > 0:
            await try_select_combobox_by_label(size_comb, "S", "Small")
        else:
            # try any comboboxes and attempt S
            combs = page.get_by_role("combobox")
            for i in range(await combs.count()):
                cb = combs.nth(i)
                if await try_select_combobox_by_label(cb, "S", "Small"):
                    break
    except Exception:
        pass

    try:
        color_comb = page.get_by_role("combobox", name="Color")
        if await color_comb.count() > 0:
            await try_select_combobox_by_label(color_comb, "Blue", "blue")
        else:
            combs = page.get_by_role("combobox")
            for i in range(await combs.count()):
                cb = combs.nth(i)
                if await try_select_combobox_by_label(cb, "Blue", "blue"):
                    break
    except Exception:
        pass

    # small pause to ensure all fields are applied
    await page.wait_for_timeout(500)

    # 5) Save the product (final action). Use role-based lookup for Save button.
    save_btn = page.get_by_role("button", name="Save")
    if await save_btn.count() > 0:
        await save_btn.click()
        # Wait for save/navigation to complete
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            await page.wait_for_timeout(2000)
    else:
        # As a fallback, try to find a button in a banner/group with name Save
        try:
            # try to find any group that contains a Save button and click it
            groups = page.get_by_role("group")
            for i in range(await groups.count()):
                grp = groups.nth(i)
                btn = grp.get_by_role("button", name="Save")
                if await btn.count() > 0:
                    await btn.click()
                    try:
                        await page.wait_for_load_state("networkidle")
                    except Exception:
                        await page.wait_for_timeout(2000)
                    break
        except Exception:
            pass

