    else:
        await page.wait_for_timeout(800)
    await page.wait_for_timeout(700)
    orders_table = None
    tables = page.get_by_role("table")
    try:
        tables_count = await tables.count()
    except Exception:
        tables_count = 0
    if tables_count == 0:
        await page.wait_for_timeout(1000)
        try:
            tables_count = await tables.count()
        except Exception:
            tables_count = 0
    for i in range(tables_count):
